+function authHeader() {
+  return `Basic ${Buffer.from(`0:${TOKEN}`).toString("base64")}`;
+}
+
+function buildUrl(path: string, query?: Record<string, any>) {
+  const normalizedPath = path.startsWith("/") ? path.slice(1) : path;
